mapper.select:
SELECT chunk_index AS chunkIndex, content
FROM document_chunk
WHERE doc_id = #{docId}
  AND version = #{version}
ORDER BY chunk_index ASC

SELECT chunk_index AS chunkIndex, content
FROM document_chunk
WHERE doc_id = #{docId}
  AND version = #{version}
ORDER BY chunk_index ASC
LIMIT #{limit} OFFSET #{offset}

SELECT chunk_id AS chunkId,
       doc_id AS docId,
       tenant_id AS tenantId,
       version,
       chunk_index AS chunkIndex,
       content,
       1 - (embedding <=> #{embedding,typeHandler=com.knowbase.vector.mybatis.PGvectorTypeHandler}) AS score
FROM document_chunk
WHERE library_id = #{libraryId}
  AND tenant_id = #{tenantId}

    AND doc_id IN

        #{id}




        AND metadata->>#{clause.field} = #{clause.value}


ORDER BY embedding <=> #{embedding,typeHandler=com.knowbase.vector.mybatis.PGvectorTypeHandler},
         chunk_id ASC
LIMIT #{topK}

SELECT chunk_id AS chunkId,
       doc_id AS docId,
       tenant_id AS tenantId,
       version,
       chunk_index AS chunkIndex,
       content,
       ts_rank_cd(to_tsvector('simple', content), plainto_tsquery('simple', #{query})) AS score
FROM document_chunk
WHERE library_id = #{libraryId}
  AND tenant_id = #{tenantId}
  AND to_tsvector('simple', content) @@ plainto_tsquery('simple', #{query})

    AND doc_id IN

        #{id}




        AND metadata->>#{clause.field} = #{clause.value}


ORDER BY score DESC, chunk_id ASC
LIMIT #{topK}
